script:
frappe.ui.form.on("Overtime Slip", {
    refresh(frm) {
        toggle_manual_edit(frm);
    },

    custom_manually_edit_hours(frm) {
        toggle_manual_edit(frm);

        if (frm.doc.custom_manually_edit_hours) {
            update_total(frm);
        }
    },

    custom_total_peak_overtime_hours(frm) {
        update_total(frm);
    },

    custom_total_holiday_overtime_hours(frm) {
        update_total(frm);
    }
});

function toggle_manual_edit(frm) {
    frm.set_df_property(
        "total_overtime_duration",
        "read_only",
        !frm.doc.custom_manually_edit_hours
    );
}

function update_total(frm) {
    // Calculate only when manual edit is enabled
    if (frm.doc.custom_manually_edit_hours) {
        let total =
            (flt(frm.doc.custom_total_peak_overtime_hours) || 0) +
            (flt(frm.doc.custom_total_holiday_overtime_hours) || 0);

        frm.set_value("total_overtime_duration", total);
    }
}

frappe.ui.form.on("Salary Slip", {
    refresh(frm) {
        set_absent_days_read_only(frm);
    },

    custom_manually_edit_absent_days(frm) {
        set_absent_days_read_only(frm);
    }
});

function set_absent_days_read_only(frm) {
    frm.set_df_property(
        "absent_days",
        "read_only",
        frm.doc.custom_manually_edit_absent_days ? 0 : 1
    );
}

frappe.ui.form.on("Salary Slip", {
    refresh(frm) {
        toggle_deduction_amount_edit(frm);
    },

    custom_manual_edit_amount(frm) {
        toggle_deduction_amount_edit(frm);
    },

    deductions_add(frm) {
        toggle_deduction_amount_edit(frm);
    }
});

function toggle_deduction_amount_edit(frm) {
    if (!frm.fields_dict.deductions) {
        return;
    }

    const read_only = !frm.doc.custom_manual_edit_amount;

    frm.fields_dict.deductions.grid.update_docfield_property(
        "amount",
        "read_only",
        read_only ? 1 : 0
    );

    frm.fields_dict.deductions.grid.refresh();
}
